#!/usr/bin/env python3
"""
Manchester editor: paste "c.709C>T" onto the canvas and it lands on the track.

A c. position is counted along the SPLICED transcript from the annotated start codon, so it is mapped
through the exons rather than by arithmetic on the track's index: c.1 is the A of the ATG, c.-12 and c.*12
are exonic positions either side of the CDS, and c.709+3 is intronic. Substitutions, del, dup, ins and
delins are placed, with ranges (c.709_711del). A transcript named in the paste (NM_004408.4:c.709C>T) picks
the track it belongs to when one is on the canvas. The reference base is checked against the track and a
mismatch is reported, since the usual cause is the coordinate belonging to another transcript.

    sudo python3 install-hgvs-c-paste.py /opt/baja-apps

Writes baja/bio/coords/cds-coords.js, baja/io/parse/parse-hgvs-c.js and baja/data/hgvs-c-paste.js, and adds
one paste branch to manchester/editor.js (backed up as editor.js.before-hgvs-c). Refuses, changing nothing,
if editor.js differs. Safe to run twice.
"""
import os, shutil, sys
HUNKS = [('                                        if (s.startsWith(`{"graph"`)) {\n                                            let js = JSON.parse(s);\n                                            await graph.setState(js)\n                                        } else if ((await exec(\'baja/data/parse-genomic-variants.js\')).isGenomicVariantText(s)) {\n                                            // "chr16:1762843 C>T" (one per line): placed on every track that covers it.\n                                            await exec(\'baja/data/genomic-variant-paste.js\', window[\'env\'][\'apiUrl\'], graph, genegraph_panel_layout, s);\n', '                                        if (s.startsWith(`{"graph"`)) {\n                                            let js = JSON.parse(s);\n                                            await graph.setState(js)\n                                        } else if ((await exec(\'baja/io/parse/parse-hgvs-c.js\')).looksLikeHgvsC(s)) {\n                                            // "c.709C>T" (one per line): counted through the exons from\n                                            // the annotated start codon, on every track it can be counted on.\n                                            await exec(\'baja/data/hgvs-c-paste.js\', window[\'env\'][\'apiUrl\'], graph, genegraph_panel_layout, s);\n                                        } else if ((await exec(\'baja/data/parse-genomic-variants.js\')).isGenomicVariantText(s)) {\n                                            // "chr16:1762843 C>T" (one per line): placed on every track that covers it.\n                                            await exec(\'baja/data/genomic-variant-paste.js\', window[\'env\'][\'apiUrl\'], graph, genegraph_panel_layout, s);\n')]
MODULES = {'baja/bio/coords/cds-coords.js': "function (track) {\n\n    // HGVS c. COORDINATES for a track, both ways.\n    //\n    //   const C = await exec('baja/bio/coords/cds-coords.js', track);\n    //   C.ok            false when the track carries no coding annotation to count from\n    //   C.toX({ pos: 709, offset: 0, region: 'cds' })   -> track x, or null\n    //   C.toC(x)        -> { pos, offset, region, text } or null\n    //   C.plus, C.cdsLength, C.startG, C.stopEndG\n    //\n    // WHAT c. ACTUALLY COUNTS. c.1 is the A of the start codon and the numbering runs along the\n    // SPLICED transcript, so it skips introns: c.709 is the 709th coding base, not the 709th\n    // base of the gene. Positions outside the CDS are written differently again -- c.-12 is 12\n    // exonic bases 5' of the A, c.*12 is 12 exonic bases 3' of the stop codon's last base -- and\n    // an intronic position hangs off the nearest exonic one, c.709+3 being 3 bases into the\n    // intron after c.709 and c.710-2 two bases before c.710.\n    //\n    // All of which is why a c. coordinate cannot be turned into a position by arithmetic on the\n    // track's own index: it needs the exons and the start codon, which is what this reads.\n    //\n    // The track is not changed.\n    return (async () => {\n        const out = { ok: false, reason: '', plus: true, cdsLength: 0, startG: null, stopEndG: null };\n        try {\n            if (!track) { out.reason = 'No track.'; return out; }\n            const A = track.annotations || [];\n            const ty = (a) => ('' + (a && a.type)).toLowerCase();\n            const sSrc = A.find((a) => {\n                const s = a && a.strand;\n                return s === '-' || s === '+' || s === 1 || s === -1 || s === '1' || s === '-1';\n            });\n            const plus = sSrc ? !(String(sSrc.strand) === '-' || String(sSrc.strand) === '-1') : (+track.strand >= 0);\n            out.plus = plus;\n\n            // Exonic positions in transcript order. A track with no exon annotation is treated as\n            // one continuous exon over its own span, which is what a cDNA track is.\n            let exons = (track.getExons ? track.getExons() : A.filter((a) => a && ty(a) === 'exon'))\n                .filter((e) => e && isFinite(+e.xi) && isFinite(+e.xf))\n                .map((e) => ({ lo: Math.min(+e.xi, +e.xf), hi: Math.max(+e.xi, +e.xf) }));\n            if (!exons.length) {\n                const lo = Math.min(+track.xi, +track.xf), hi = Math.max(+track.xi, +track.xf);\n                if (!isFinite(lo) || !isFinite(hi)) { out.reason = 'That track has no exons and no span.'; return out; }\n                exons = [{ lo: lo, hi: hi }];\n            }\n            exons.sort((a, b) => plus ? a.lo - b.lo : b.lo - a.lo);\n            const tx = [];                       // tx[i] = genomic position of transcript base i\n            for (const e of exons) {\n                if (plus) { for (let p = e.lo; p <= e.hi; p++) tx.push(p); }\n                else { for (let p = e.hi; p >= e.lo; p--) tx.push(p); }\n            }\n            const idxOf = new Map();\n            for (let i = 0; i < tx.length; i++) if (!idxOf.has(tx[i])) idxOf.set(tx[i], i);\n\n            // The CDS: its first base is c.1 and its last base is the end of the stop codon.\n            const tr = A.find((a) => ty(a) === 'translation');\n            const cds = A.filter((a) => a && a.type === 'CDS');\n            let startG = null, stopEndG = null;\n            if (tr && tr.xi != null && tr.xf != null) {\n                const lo = Math.min(+tr.xi, +tr.xf), hi = Math.max(+tr.xi, +tr.xf);\n                startG = plus ? lo : hi; stopEndG = plus ? hi : lo;\n            } else if (cds.length) {\n                let lo = Infinity, hi = -Infinity;\n                for (const c of cds) { lo = Math.min(lo, +c.xi, +c.xf); hi = Math.max(hi, +c.xi, +c.xf); }\n                startG = plus ? lo : hi; stopEndG = plus ? hi : lo;\n            } else {\n                const tss = A.find((a) => ty(a) === 'tss');\n                if (tss && tss.xi != null) startG = plus ? Math.min(+tss.xi, +tss.xf) : Math.max(+tss.xi, +tss.xf);\n            }\n            if (startG == null || !isFinite(startG) || !idxOf.has(startG)) {\n                out.reason = 'That track has no annotated start codon, so c. positions cannot be counted on it.';\n                return out;\n            }\n            const s0 = idxOf.get(startG);                                  // transcript index of c.1\n            const sEnd = (stopEndG != null && idxOf.has(stopEndG)) ? idxOf.get(stopEndG) : null;\n            out.ok = true; out.startG = startG; out.stopEndG = stopEndG;\n            out.cdsLength = (sEnd != null) ? (sEnd - s0 + 1) : (tx.length - s0);\n\n            // transcript index for a c. position, before any intronic offset\n            const indexFor = (pos, region) => {\n                if (region === 'utr5') return s0 - Math.abs(pos);          // c.-n\n                if (region === 'utr3') return (sEnd == null ? null : sEnd + Math.abs(pos));   // c.*n\n                return s0 + (pos - 1);                                      // c.n\n            };\n            const inTrack = (p) => {\n                const lo = Math.min(+track.xi, +track.xf), hi = Math.max(+track.xi, +track.xf);\n                return isFinite(p) && p >= lo && p <= hi;\n            };\n\n            out.toX = (c) => {\n                try {\n                    if (!c || c.pos == null) return null;\n                    const region = c.region || 'cds';\n                    const i = indexFor(+c.pos, region);\n                    if (i == null || i < 0 || i >= tx.length) return null;\n                    const x = tx[i];\n                    const off = Math.round(+c.offset || 0);\n                    if (!off) return x;\n                    // An intronic offset walks the GENOME from that exonic base, in transcript\n                    // direction, which is how +n and -n are defined.\n                    const p = plus ? (x + off) : (x - off);\n                    return inTrack(p) ? p : null;\n                } catch (e) { return null; }\n            };\n\n            out.toC = (x) => {\n                try {\n                    const p = Math.round(+x);\n                    if (idxOf.has(p)) {\n                        const i = idxOf.get(p);\n                        if (sEnd != null && i > sEnd) return { pos: i - sEnd, offset: 0, region: 'utr3', text: 'c.*' + (i - sEnd) };\n                        if (i < s0) return { pos: -(s0 - i), offset: 0, region: 'utr5', text: 'c.' + (i - s0) };\n                        return { pos: i - s0 + 1, offset: 0, region: 'cds', text: 'c.' + (i - s0 + 1) };\n                    }\n                    // Intronic: hang it off the nearer exonic neighbour, the way HGVS writes it.\n                    let best = null;\n                    for (let k = 1; k <= 50000; k++) {\n                        const up = plus ? p - k : p + k, dn = plus ? p + k : p - k;\n                        if (idxOf.has(up)) { best = { base: up, off: k }; break; }\n                        if (idxOf.has(dn)) { best = { base: dn, off: -k }; break; }\n                        if (!inTrack(up) && !inTrack(dn)) break;\n                    }\n                    if (!best) return null;\n                    const b = out.toC(best.base);\n                    if (!b) return null;\n                    const sign = best.off > 0 ? '+' : '-';\n                    return { pos: b.pos, offset: best.off, region: b.region,\n                        text: b.text + sign + Math.abs(best.off) };\n                } catch (e) { return null; }\n            };\n            return out;\n        } catch (e) {\n            out.reason = 'Could not read c. coordinates: ' + (e && e.message ? e.message : e);\n            return out;\n        }\n    })();\n}\n", 'baja/io/parse/parse-hgvs-c.js': "function () {\n\n    // Parse HGVS coding-sequence variants: c.709C>T and the rest of the c. grammar.\n    //\n    //   const P = await exec('baja/io/parse/parse-hgvs-c.js');\n    //   P('c.709C>T')            -> [{ kind:'sub', pos:709, offset:0, region:'cds', ref:'C', alt:'T', … }]\n    //   P.looksLikeHgvsC(text)   -> true when EVERY non-empty line is one c. variant\n    //\n    // Understood, with or without a transcript prefix (NM_000539.3:, ENST00000296930.9:,\n    // DNM1(NM_004408.4):, a bare gene name:):\n    //\n    //   c.709C>T              substitution\n    //   c.709del              one base deleted            c.709_711del      a run deleted\n    //   c.709dup              one base duplicated         c.709_710dup      a run duplicated\n    //   c.709_710insAT        bases inserted BETWEEN two positions\n    //   c.709delinsGG         one base replaced by others c.709_711delinsG  a run replaced\n    //\n    // Positions follow the c. grammar: a plain number inside the CDS, -n in the 5' UTR, *n in\n    // the 3' UTR, and either of those plus an intronic offset (c.709+3, c.710-2, c.*12+1).\n    // r. and n. are accepted as the same shape, since the arithmetic is identical; p. (protein)\n    // is NOT, because a residue is not a base and guessing which codon position was meant would\n    // be inventing data.\n    //\n    // Each result: { kind, pos, offset, region, posEnd, offsetEnd, regionEnd, ref, alt, prefix,\n    //                label, raw }  with kind 'sub' | 'del' | 'dup' | 'ins' | 'delins'.\n    const POS = '(\\\\*|-)?(\\\\d{1,9})([+-]\\\\d{1,6})?';\n    const mkPos = (star, num, off) => ({\n        region: star === '*' ? 'utr3' : (star === '-' ? 'utr5' : 'cds'),\n        pos: star === '-' ? -parseInt(num, 10) : parseInt(num, 10),\n        offset: off ? parseInt(off, 10) : 0\n    });\n    // <prefix>:  c. | r. | n.  <pos>[ _<pos>] <change>\n    const RE = new RegExp(\n        '^\\\\s*(?:([A-Za-z0-9_.()-]+)\\\\s*:\\\\s*)?[crn]\\\\.\\\\s*'\n        + POS + '(?:_' + POS + ')?'\n        + '\\\\s*(?:'\n        + '([ACGTU]+)\\\\s*>\\\\s*([ACGTU]+)'            // 5,6  sub\n        + '|delins([ACGTU]+)'                        // 7    delins\n        + '|del([ACGTU]*)'                           // 8    del\n        + '|dup([ACGTU]*)'                           // 9    dup\n        + '|ins([ACGTU]+)'                           // 10   ins\n        + ')\\\\s*$', 'i');\n\n    const one = (line) => {\n        const s = ('' + (line == null ? '' : line)).trim().replace(/\\s*\\([^)]*\\)\\s*$/, '').trim();\n        if (!s) return null;\n        const m = s.match(RE);\n        if (!m) return null;\n        const a = mkPos(m[2], m[3], m[4]);\n        const b = m[6] ? mkPos(m[5], m[6], m[7]) : null;\n        const up = (v) => ('' + (v || '')).toUpperCase().replace(/U/g, 'T');\n        let kind, ref = '', alt = '';\n        if (m[8] && m[9]) { kind = 'sub'; ref = up(m[8]); alt = up(m[9]); }\n        else if (m[10] != null && m[10] !== '') { kind = 'delins'; alt = up(m[10]); }\n        else if (m[11] != null) { kind = 'del'; ref = up(m[11]); }\n        else if (m[12] != null) { kind = 'dup'; ref = up(m[12]); }\n        else if (m[13]) { kind = 'ins'; alt = up(m[13]); }\n        else return null;\n        // An insertion is written between two positions, so it needs both; everything else may\n        // name one position or a range.\n        if (kind === 'ins' && !b) return null;\n        if (kind === 'sub' && b) return null;\n        return {\n            kind: kind, prefix: m[1] || '', raw: s,\n            pos: a.pos, offset: a.offset, region: a.region,\n            posEnd: b ? b.pos : a.pos, offsetEnd: b ? b.offset : a.offset, regionEnd: b ? b.region : a.region,\n            ref: ref, alt: alt,\n            label: (m[1] ? m[1] + ':' : '') + s.replace(/^.*?[crn]\\./i, 'c.')\n        };\n    };\n\n    const parse = (text) => {\n        const out = [];\n        for (const line of ('' + (text || '')).split(/[\\r\\n,;]+/)) {\n            const v = one(line);\n            if (v) out.push(v);\n        }\n        return out;\n    };\n    // Only when the paste is c. variants and nothing else: a sentence that happens to mention\n    // one belongs to the routes that read sentences.\n    parse.looksLikeHgvsC = (text) => {\n        const lines = ('' + (text || '')).split(/[\\r\\n,;]+/).map((l) => l.trim()).filter(Boolean);\n        return lines.length > 0 && lines.length <= 500 && lines.every((l) => !!one(l));\n    };\n    parse.one = one;\n    return parse;\n}\n", 'baja/data/hgvs-c-paste.js': 'function (server, graph, genegraph_panel_layout, text) {\n\n    // PASTED c. VARIANTS: "c.709C>T" dropped on the canvas, placed on every track whose\n    // transcript the coordinate can be counted on.\n    //\n    //   exec(\'baja/data/hgvs-c-paste.js\', server, graph, genegraph_panel_layout, text)\n    //\n    // A c. position is TRANSCRIPT-SPECIFIC: c.709 is the 709th base of a particular coding\n    // sequence, so the same string lands at different places on two transcripts of one gene and\n    // means nothing at all on a track with no start codon annotated. That is the whole\n    // difference from a genomic paste, and it is why this route exists:\n    //\n    //   * the position is counted through the exons from the annotated start codon\n    //     (baja/bio/coords/cds-coords.js), never by arithmetic on the track\'s own index;\n    //   * a transcript named in the paste (NM_004408.4:c.709C>T) picks the track it belongs to\n    //     when one is on the canvas, rather than scattering the variant over all of them;\n    //   * the reference base is checked against the track and a mismatch is reported, because\n    //     the usual cause is the coordinate belonging to another transcript.\n    //\n    // Resolves { placed, tracks, unplaced, mismatched }.\n    const say = (m, secs) => { try { graph.setMessage(\' \' + m + \' \', secs); } catch (e) { } };\n    const restoreHover = () => { try { exec(\'baja/manchester/menu/mouse-over-highlight.js\', graph, genegraph_panel_layout); } catch (e) { } };\n\n    return (async () => {\n        const P = await exec(\'baja/io/parse/parse-hgvs-c.js\');\n        const vars = P(text);\n        if (!vars.length) { say(\'No c. variants found in the paste.\', 3); return { placed: 0, tracks: 0, unplaced: [], mismatched: [] }; }\n\n        let SnpIndel = null;\n        try { SnpIndel = await exec(\'flexigraph/snpindel.js\'); } catch (e) { }\n        if (!SnpIndel) { say(\'Variant support unavailable.\', 3); return { placed: 0, tracks: 0, unplaced: vars, mismatched: [] }; }\n\n        const COMP = { A: \'T\', T: \'A\', C: \'G\', G: \'C\', N: \'N\' };\n        const tracks = ((graph && graph.track) || []).filter(Boolean);\n        // The c. coordinate system of each track, built once.\n        const coords = [];\n        for (const t of tracks) {\n            let C = null;\n            try { C = await exec(\'baja/bio/coords/cds-coords.js\', t); } catch (e) { C = null; }\n            if (C && C.ok) coords.push({ track: t, C: C });\n        }\n        if (!coords.length) {\n            say(\'No track on the canvas has an annotated start codon, so a c. position cannot be counted. Load a transcript with its CDS first.\', 6);\n            return { placed: 0, tracks: 0, unplaced: vars, mismatched: [] };\n        }\n\n        // A transcript named in the paste narrows it to the track that carries that name.\n        const nameOf = (t) => (\'\' + (t.name || t.id || \'\')).toLowerCase();\n        const pickFor = (v) => {\n            const pre = (\'\' + (v.prefix || \'\')).toLowerCase().replace(/^.*\\(|\\).*$/g, \'\');\n            if (!pre) return coords;\n            const bare = pre.replace(/\\.\\d+$/, \'\');\n            const hit = coords.filter((c) => {\n                const n = nameOf(c.track);\n                return n && (n.indexOf(pre) >= 0 || n.indexOf(bare) >= 0\n                    || (\'\' + (c.track.id || \'\')).toLowerCase().indexOf(bare) >= 0);\n            });\n            return hit.length ? hit : coords;\n        };\n\n        const touched = new Set(), unplaced = [], mismatched = [];\n        let placed = 0, pushed = false;\n\n        for (const v of vars) {\n            let hits = 0;\n            for (const { track, C } of pickFor(v)) {\n                const xa = C.toX({ pos: v.pos, offset: v.offset, region: v.region });\n                const xb = C.toX({ pos: v.posEnd, offset: v.offsetEnd, region: v.regionEnd });\n                if (xa == null || xb == null) continue;\n\n                // What the track reads there, in transcript orientation.\n                const seq = (\'\' + (track.sequence || \'\')).toUpperCase();\n                const txi = +track.xi || 0;\n                const readAt = (p) => {\n                    const i = Math.round(p) - txi;\n                    if (i < 0 || i >= seq.length) return \'\';\n                    const b = seq[i] || \'\';\n                    return C.plus ? b : (COMP[b] || \'\');\n                };\n                const lo = Math.min(xa, xb), hi = Math.max(xa, xb);\n                const spanRef = [];\n                for (let p = (C.plus ? lo : hi); C.plus ? p <= hi : p >= lo; p += (C.plus ? 1 : -1)) spanRef.push(readAt(p));\n                const reads = spanRef.join(\'\');\n\n                // The reference the paste claims, where it carries one.\n                if (v.ref && reads && v.ref !== reads) {\n                    mismatched.push(v.label + \' on \' + (track.name || \'track\') + \': says \' + v.ref + \', track reads \' + reads);\n                    continue;\n                }\n\n                // HGVS -> the VCF-shaped alleles a SnpIndel is built from, anchored on the base\n                // before the change for an indel, which is how every other route stores them.\n                let type = \'snp\', ref = \'\', alt = \'\', anchorX = xa;\n                if (v.kind === \'sub\') { type = \'snp\'; ref = v.ref || reads; alt = v.alt; }\n                else if (v.kind === \'del\') {\n                    type = \'del\';\n                    const before = C.plus ? lo - 1 : hi + 1;\n                    anchorX = before; ref = readAt(before) + reads; alt = readAt(before);\n                } else if (v.kind === \'dup\') {\n                    type = \'ins\';\n                    const before = C.plus ? hi : lo;        // duplicated run is inserted after it\n                    anchorX = before; ref = readAt(before); alt = readAt(before) + reads;\n                } else if (v.kind === \'ins\') {\n                    type = \'ins\';\n                    anchorX = xa;                            // between xa and xb\n                    ref = readAt(xa); alt = readAt(xa) + v.alt;\n                } else if (v.kind === \'delins\') {\n                    const before = C.plus ? lo - 1 : hi + 1;\n                    anchorX = before;\n                    ref = readAt(before) + reads; alt = readAt(before) + v.alt;\n                    type = (alt.length > ref.length) ? \'ins\' : (alt.length < ref.length ? \'del\' : \'snp\');\n                    if (type === \'snp\') { anchorX = xa; ref = reads; alt = v.alt; }\n                }\n                if (!ref || !alt) continue;\n\n                if (!pushed) { try { graph.pushOntoHistory(); } catch (e) { } pushed = true; }\n                try {\n                    // transcriptStrand, so SnpIndel keeps the right complemented copy for a\n                    // minus-strand gene -- the same convention the VCF route uses.\n                    const snp = new SnpIndel(type, Math.round(anchorX), ref, alt, 0,\n                        C.plus ? 1 : -1, v.label, null, null);\n                    snp.name = v.label;\n                    snp.source = \'Pasted (c.)\';\n                    try { snp.setAnnotation([\'HGVSc=\' + v.label]); } catch (e) { }\n                    track.addsnpindel(snp);\n                    track.showSnpIndels = true;\n                    touched.add(track); hits++; placed++;\n                } catch (e) { }\n            }\n            if (!hits) unplaced.push(v);\n        }\n        try { if (graph.wake) graph.wake(); } catch (e) { }\n\n        const plural = (n, w) => n + \' \' + w + (n === 1 ? \'\' : \'s\');\n        let msg = \'\';\n        if (placed) msg = \'Placed \' + plural(vars.length - unplaced.length, \'c. variant\') + \' on \' + plural(touched.size, \'track\') + \'.\';\n        if (mismatched.length) msg += \' \' + plural(mismatched.length, \'mismatch\') + \': \' + mismatched.slice(0, 2).join(\'; \')\n            + (mismatched.length > 2 ? \'; …\' : \'\') + \'. A c. position belongs to one transcript: check it is this one.\';\n        if (unplaced.length && !placed) {\n            msg = \'Could not place \' + unplaced.map((v) => v.label).join(\', \')\n                + (mismatched.length ? \'. \' + mismatched.slice(0, 2).join(\'; \') : \'\')\n                + \'. The position may lie outside this transcript, or belong to another one.\';\n        } else if (unplaced.length) {\n            msg += \' \' + plural(unplaced.length, \'variant\') + \' could not be placed.\';\n        }\n        say(msg, 6);\n        restoreHover();\n        return { placed, tracks: touched.size, unplaced, mismatched };\n    })();\n}\n'}
MARK = 'hgvs-c-paste.js'
root = os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '~/baja-apps')
p = os.path.join(root, 'manchester/editor.js')
if not os.path.isfile(p):
    sys.exit('Not found: ' + p)
s = open(p, encoding='utf-8').read()
crlf = '\r\n' in s
s = s.replace('\r\n', '\n')
todo = MARK not in s
if todo:
    for old, new in HUNKS:
        if s.count(old) != 1:
            sys.exit(p + ' differs from the version this update was made against'
                     + ' (install-genomic-variant-paste.py first?). Nothing was changed.')
        s = s.replace(old, new, 1)
for rel, text in MODULES.items():
    m = os.path.join(root, rel)
    os.makedirs(os.path.dirname(m), exist_ok=True)
    open(m, 'w', encoding='utf-8').write(text)
    print('Wrote', m)
if todo:
    shutil.copyfile(p, p + '.before-hgvs-c')
    open(p, 'w', encoding='utf-8', newline='').write(s.replace('\n', '\r\n') if crlf else s)
    print('Updated', p)
else:
    print('Already installed:', p)
print('Restart baja-server (it caches scripts), then hard-refresh the editor (Ctrl+Shift+R).')
